import AnyLanguageModel

/// The result of applying one compaction policy.
///
/// `Output` is the value generated by the model. Hail does not interpret its
/// fields. `through` is the last turn whose work the summary covers, chosen by the
/// compaction policy and replayed against the event-sourced agent history.
public struct CompactionResult<Output: Codable & Sendable & Generable>: Codable, Sendable {
    public let output: Output
    /// The structured value inserted into the next model context. It may be
    /// a projection of `output`; Hail does not assume that every generated
    /// field belongs in the agent's history.
    public let context: GeneratedContent
    public let through: AgentHistory.Cut
    /// Which archived inputs stay word for word.
    public let kept: AgentHistory.KeptInputs

    public init(
        output: Output,
        context: GeneratedContent,
        through: AgentHistory.Cut,
        kept: AgentHistory.KeptInputs
    ) {
        self.output = output
        self.context = context
        self.through = through
        self.kept = kept
    }
}

extension CompactionResult: Equatable where Output: Equatable {}
